if(result.schema_version!=='1.0.0'||result.run_id!==source.run_id)errors.push('identity mismatch');
if(!['complete','partial','no_requirements'].includes(result.extraction_status))errors.push('invalid extraction_status');
for(const field of ['items','contradictions','missing_information'])if(!Array.isArray(result[field]))errors.push(field+' must be an array');
const sourceMap=Object.fromEntries((source.sources||[]).map(entry=>[entry.source_id,entry]));
const validateEvidence=(record,label)=>{if(!Array.isArray(record.evidence)||record.evidence.length===0){errors.push(label+' has no evidence');return;}for(const evidence of record.evidence){const matchingSource=sourceMap[evidence.source_id];if(!matchingSource){errors.push('unknown source ID for '+label);continue;}const citation=(matchingSource.citations||[]).find(entry=>entry.quote===evidence.quote&&entry.location===evidence.location);if(!citation){errors.push('citation mismatch for '+label);continue;}if(evidence.source_type!==matchingSource.source_type||evidence.source_name!==matchingSource.source_name||evidence.content_hash!==matchingSource.content_hash||(citation.speaker||undefined)!==(evidence.speaker||undefined))errors.push('provenance mismatch for '+label);}};
if(Array.isArray(result.items))for(const [index,item]of result.items.entries()){if(!item.id||!item.type||!item.statement||!item.status)errors.push('item '+index+' missing required identity fields');if(source.source_route==='production_multi_source')validateEvidence(item,item.id||'item '+index);}
